// Junta todas las páginas devueltas por la paginación en un solo array de contactos.
// Es defensivo respecto a la forma real de la respuesta (no confirmada todavía):
// puede venir como array plano, o envuelta en {data:[...]}, {users:[...]}, etc.
const items = $input.all();
const contactos = [];

for (const item of items) {
  const body = item.json;
  let arr = null;

  if (Array.isArray(body)) {
    arr = body;
  } else if (body && typeof body === 'object') {
    const candidateKeys = ['data', 'users', 'contacts', 'subscribers', 'results', 'items'];
    for (const key of candidateKeys) {
      if (Array.isArray(body[key])) {
        arr = body[key];
        break;
      }
    }
  }

  if (arr) {
    contactos.push(...arr);
  }
}

return contactos.map(c => ({ json: c }));

// Normaliza cada contacto probando varios nombres de campo posibles,
// porque todavía no confirmamos el shape exacto del endpoint bulk.
// `raw_keys` queda de diagnóstico: si telefono_encontrado da false en
// la mayoría, ahí se ve el nombre real del campo para ajustar el mapeo.
return $input.all().map(item => {
  const c = item.json || {};

  const id = c.id ?? c.user_id ?? c._id ?? null;

  const nombre = c.full_name
    || [c.first_name, c.last_name].filter(Boolean).join(' ').trim()
    || c.name
    || null;

  const telefono = c.phone
    || c.phone_number
    || c.whatsapp_phone
    || c.wa_phone
    || c.whatsapp
    || null;

  return {
    json: {
      id,
      nombre: nombre || null,
      telefono: telefono || null,
      telefono_encontrado: Boolean(telefono),
      canal: c.channel ?? null,
      suscrito: c.subscribed ?? null,
      archivado: c.archived ?? null,
      bloqueado: c.blocked ?? null,
      raw_keys: Object.keys(c)
    }
  };
});
